// Quick validation test script
const http = require('http');

const testCases = [
  {
    name: 'Missing name field',
    data: {},
    expectedStatus: 400,
    expectedMessage: 'Missing required field: name'
  },
  {
    name: 'Non-string name',
    data: { name: 123 },
    expectedStatus: 400,
    expectedMessage: 'Field "name" must be a string'
  },
  {
    name: 'Empty name string',
    data: { name: '' },
    expectedStatus: 400,
    expectedMessage: 'Field "name" cannot be empty'
  },
  {
    name: 'Whitespace-only name',
    data: { name: '   ' },
    expectedStatus: 400,
    expectedMessage: 'Field "name" cannot be empty'
  },
  {
    name: 'Valid name',
    data: { name: 'Charlie' },
    expectedStatus: 201,
    expectedMessage: 'User created successfully'
  }
];

function runTest(testCase) {
  return new Promise((resolve, reject) => {
    const options = {
      hostname: 'localhost',
      port: 3000,
      path: '/users',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      }
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        const response = JSON.parse(data);
        const passed = res.statusCode === testCase.expectedStatus && 
                      (response.message === testCase.expectedMessage || 
                       response.error === 'Bad Request');

        resolve({
          name: testCase.name,
          passed,
          expectedStatus: testCase.expectedStatus,
          actualStatus: res.statusCode,
          expectedMessage: testCase.expectedMessage,
          actualMessage: response.message || response.error
        });
      });
    });

    req.on('error', (error) => {
      reject({
        name: testCase.name,
        passed: false,
        error: error.message
      });
    });

    req.write(JSON.stringify(testCase.data));
    req.end();
  });
}

async function runAllTests() {
  console.log('Starting validation tests...\n');

  for (const testCase of testCases) {
    try {
      const result = await runTest(testCase);
      if (result.passed) {
        console.log(`✅ ${result.name}`);
      } else {
        console.log(`❌ ${result.name}`);
        console.log(`   Expected: ${result.expectedStatus} - "${result.expectedMessage}"`);
        console.log(`   Got: ${result.actualStatus} - "${result.actualMessage}"`);
      }
    } catch (error) {
      console.log(`❌ ${error.name} - Error: ${error.error}`);
    }
  }
}

// Check if server is running
const checkServer = new Promise((resolve, reject) => {
  const req = http.get('http://localhost:3000/health', (res) => {
    if (res.statusCode === 200) {
      resolve(true);
    } else {
      reject(new Error(`Health check failed with status ${res.statusCode}`));
    }
  });

  req.on('error', () => {
    reject(new Error('Server is not running. Please start the server first with: node app.js'));
  });

  req.end();
});

checkServer
  .then(() => runAllTests())
  .catch(error => {
    console.log(`⚠️  ${error.message}`);
    console.log('\nTo run tests:');
    console.log('1. Start the server: node app.js');
    console.log('2. Run tests: node test-validation.js');
  });

