// Production-ready Express API with input validation
const express = require('express');

// Initialize Express app
const app = express();

// Security and production middleware
app.use(express.json({ limit: '10kb' })); // Limit payload size

// Request logging middleware (for production)
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.path} ${res.statusCode} - ${duration}ms`);
  });
  next();
});

// Health check endpoint (for load balancers and monitoring)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    service: 'express-validation-api',
    version: '1.0.0'
  });
});

// GET users endpoint
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// POST users endpoint with comprehensive input validation
app.post('/users', (req, res) => {
  try {
    const { name } = req.body;

    // Validate the name field is present
    if (!name) {
      return res.status(400).json({ 
        error: 'Missing required field: name',
        code: 'VALIDATION_ERROR'
      });
    }

    // Validate the name field is a string
    if (typeof name !== 'string') {
      return res.status(400).json({ 
        error: 'Field "name" must be a string',
        code: 'VALIDATION_ERROR'
      });
    }

    // Additional validation: name should not be empty or only whitespace
    if (name.trim().length === 0) {
      return res.status(400).json({ 
        error: 'Field "name" cannot be empty',
        code: 'VALIDATION_ERROR'
      });
    }

    // Additional validation: reasonable length limit
    if (name.length > 100) {
      return res.status(400).json({ 
        error: 'Field "name" must be less than 100 characters',
        code: 'VALIDATION_ERROR'
      });
    }

    // For production, you would typically:
    // 1. Sanitize input
    // 2. Save to database
    // 3. Generate proper ID (not timestamp-based in production)
    const newUser = {
      id: Date.now(), // In production, use proper ID generation
      name: name.trim(), // Sanitize by trimming whitespace
      createdAt: new Date().toISOString()
    };

    res.status(201).json({ 
      message: 'User created successfully',
      user: newUser
    });

  } catch (error) {
    console.error('Error processing POST /users:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      code: 'INTERNAL_ERROR'
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.path
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({
    error: 'Internal server error',
    code: 'INTERNAL_ERROR'
  });
});

// Get port from environment or default
const PORT = process.env.PORT || 3000;

// Start server
const server = app.listen(PORT, () => {
  console.log(`Server running in ${process.env.NODE_ENV || 'development'} mode on port ${PORT}`);
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = { app, server };

