// Validation test file
const request = require('supertest');
const { app } = require('../app');

describe('POST /users validation', () => {
  it('should return 400 when name is missing', async () => {
    const response = await request(app)
      .post('/users')
      .send({});

    expect(response.status).toBe(400);
    expect(response.body.error).toContain('Missing required field');
    expect(response.body.code).toBe('VALIDATION_ERROR');
  });

  it('should return 400 when name is not a string', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 123 });

    expect(response.status).toBe(400);
    expect(response.body.error).toContain('must be a string');
    expect(response.body.code).toBe('VALIDATION_ERROR');
  });

  it('should return 400 when name is empty string', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '' });

    expect(response.status).toBe(400);
    expect(response.body.error).toContain('cannot be empty');
    expect(response.body.code).toBe('VALIDATION_ERROR');
  });

  it('should return 400 when name is only whitespace', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '   ' });

    expect(response.status).toBe(400);
    expect(response.body.error).toContain('cannot be empty');
    expect(response.body.code).toBe('VALIDATION_ERROR');
  });

  it('should return 400 when name is too long', async () => {
    const longName = 'a'.repeat(101);
    const response = await request(app)
      .post('/users')
      .send({ name: longName });

    expect(response.status).toBe(400);
    expect(response.body.error).toContain('less than 100 characters');
    expect(response.body.code).toBe('VALIDATION_ERROR');
  });

  it('should return 201 when name is valid', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 'John Doe' });

    expect(response.status).toBe(201);
    expect(response.body.message).toBe('User created successfully');
    expect(response.body.user.name).toBe('John Doe');
    expect(response.body.user.id).toBeDefined();
    expect(response.body.user.createdAt).toBeDefined();
  });

