// Simple test script to verify our POST validation works
const http = require('http');

const testCases = [
  {
    name: 'Missing name field',
    body: { email: 'test@example.com' },
    expectedStatus: 400,
    expectedError: 'Missing required field: name'
  },
  {
    name: 'Non-string name (number)',
    body: { name: 123 },
    expectedStatus: 400,
    expectedError: 'Field "name" must be a string'
  },
  {
    name: 'Non-string name (null)',
    body: { name: null },
    expectedStatus: 400,
    expectedError: 'Field "name" must be a string'
  },
  {
    name: 'Empty string name',
    body: { name: '' },
    expectedStatus: 400,
    expectedError: 'Field "name" cannot be empty or whitespace only'
  },
  {
    name: 'Whitespace-only name',
    body: { name: '   ' },
    expectedStatus: 400,
    expectedError: 'Field "name" cannot be empty or whitespace only'
  },
  {
    name: 'Valid name',
    body: { name: 'John Doe' },
    expectedStatus: 201,
    expectedMessage: 'User created successfully'
  }
];

function runTest(testCase) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(testCase.body);

    const options = {
      hostname: 'localhost',
      port: 3000,
      path: '/users',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        try {
          const response = JSON.parse(data || '{}');
          const passed = 
            res.statusCode === testCase.expectedStatus && 
            (testCase.expectedError ? response.error === testCase.expectedError : 
             testCase.expectedMessage ? response.message === testCase.expectedMessage : true);

          resolve({
            name: testCase.name,
            passed,
            expectedStatus: testCase.expectedStatus,
            actualStatus: res.statusCode,
            expectedError: testCase.expectedError,
            actualError: response.error,
            expectedMessage: testCase.expectedMessage,
            actualMessage: response.message
          });
        } catch (e) {
          reject(e);
        }
      });
    });

    req.on('error', (e) => {
      reject(e);
    });

    req.write(postData);
    req.end();
  });
}

// Export for manual testing
module.exports = { testCases, runTest };

// If run directly, assume server is running
if (require.main === module) {
  console.log('Starting validation tests...');
  console.log('Make sure the server is running on port 3000 first!\n');

  Promise.all(testCases.map(runTest))
    .then(results => {
      let passed = 0;
      let failed = 0;

      results.forEach(result => {
        if (result.passed) {
          console.log(`✅ ${result.name}`);
          passed++;
        } else {
          console.log(`❌ ${result.name}`);
          console.log(`   Expected status: ${result.expectedStatus}, Got: ${result.actualStatus}`);
          if (result.expectedError) {
            console.log(`   Expected error: "${result.expectedError}"`);
            console.log(`   Got error: "${result.actualError}"`);
          }
          if (result.expectedMessage) {
            console.log(`   Expected message: "${result.expectedMessage}"`);
            console.log(`   Got message: "${result.actualMessage}"`);
          }
          failed++;
        }
      });

      console.log(`\nResults: ${passed} passed, ${failed} failed`);
      process.exit(failed > 0 ? 1 : 0);
    })
    .catch(err => {
      console.error('Test error:', err.message);
      console.log('\n⚠️  Make sure the server is running on port 3000!');
      process.exit(1);
    });
}

