const request = require('supertest');
const app = require('../app');

describe('POST /users input validation', () => {
  test('should reject request with missing name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({});

    expect(response.status).toBe(400);
    expect(response.body.error).toContain('Missing required field: name');
  });

  test('should reject request with non-string name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 123 });

    expect(response.status).toBe(400);
    expect(response.body.error).toContain('Invalid data type: name must be a string');
  });

  test('should reject request with empty name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '' });

    expect(response.status).toBe(400);
    expect(response.body.error).toContain('Name field cannot be empty or whitespace only');
  });

  test('should reject request with whitespace-only name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '   ' });

    expect(response.status).toBe(400);
    expect(response.body.error).toContain('Name field cannot be empty or whitespace only');
  });

  test('should accept valid request with string name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 'Charlie' });

    expect(response.status).toBe(201);
    expect(response.body.message).toBe('User created successfully');
    expect(response.body.user.name).toBe('Charlie');
  });

  test('should trim whitespace from valid name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '  Charlie  ' });

    expect(response.status).toBe(201);
    expect(response.body.user.name).toBe('Charlie');
  });
});

describe('GET endpoints', () => {
  test('should return health status', async () => {
    const response = await request(app).get('/health');
    expect(response.status).toBe(200);
    expect(response.body.status).toBe('ok');
  });

  test('should return users list', async () => {
    const response = await request(app).get('/users');
    expect(response.status).toBe(200);
    expect(Array.isArray(response.body)).toBe(true);
    expect(response.body.length).toBeGreaterThan(0);
  });
});

module.exports = {
  testEnvironment: 'node',
  testMatch: ['**/test/**/*.test.js'],
  collectCoverage: true,
  coverageDirectory: 'coverage',
  coverageReporters: ['text', 'lcov'],
  verbose: true
};

