#!/usr/bin/env node

const http = require('http');

const tests = [
  {
    name: 'Valid request',
    data: { name: 'Charlie' },
    expectedStatus: 201
  },
  {
    name: 'Missing name field',
    data: {},
    expectedStatus: 400
  },
  {
    name: 'Non-string name',
    data: { name: 123 },
    expectedStatus: 400
  },
  {
    name: 'Empty name',
    data: { name: '' },
    expectedStatus: 400
  },
  {
    name: 'Whitespace-only name',
    data: { name: '   ' },
    expectedStatus: 400
  }
];

let passed = 0;
let failed = 0;

function runTest(test, index) {
  return new Promise((resolve) => {
    const data = JSON.stringify(test.data);

    const options = {
      hostname: 'localhost',
      port: 3000,
      path: '/users',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': data.length
      }
    };

    const req = http.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => body += chunk);
      res.on('end', () => {
        const success = res.statusCode === test.expectedStatus;

        if (success) {
          console.log(`✓ Test ${index + 1}: ${test.name}`);
          passed++;
        } else {
          console.log(`✗ Test ${index + 1}: ${test.name}`);
          console.log(`  Expected: ${test.expectedStatus}, Got: ${res.statusCode}`);
          console.log(`  Response: ${body}`);
          failed++;
        }
        resolve();
      });
    });

    req.on('error', (err) => {
      console.log(`✗ Test ${index + 1}: ${test.name} - Error: ${err.message}`);
      failed++;
      resolve();
    });

    req.write(data);
    req.end();
  });
}

async function runAllTests() {
  console.log('Starting validation tests...\n');

  for (let i = 0; i < tests.length; i++) {
    await runTest(tests[i], i);
  }

  console.log('\n=== Test Summary ===');
  console.log(`Passed: ${passed}`);
  console.log(`Failed: ${failed}`);
  console.log(`Total: ${tests.length}`);

  process.exit(failed > 0 ? 1 : 0);
}

// Check if server is running
const checkReq = http.request({
  hostname: 'localhost',
  port: 3000,
  path: '/health',
  method: 'GET',
  timeout: 2000
}, () => {
  runAllTests();
});

checkReq.on('error', () => {
  console.error('Error: Server is not running on port 3000');
  console.error('Please start the server with: npm start');
  process.exit(1);
});

