const axios = require('axios');

async function testValidation() {
  const baseUrl = 'http://localhost:3000';

  console.log('Testing POST /users validation...\n');

  // Test 1: Missing name field
  console.log('Test 1: Missing name field');
  try {
    const response1 = await axios.post(`${baseUrl}/users`, {});
    console.log('FAIL: Should have returned 400');
  } catch (error) {
    if (error.response && error.response.status === 400) {
      console.log('PASS: Returned 400 status');
      console.log('Message:', error.response.data.message);
    } else {
      console.log('FAIL:', error.message);
    }
  }
  console.log('---');

  // Test 2: Non-string name
  console.log('Test 2: Non-string name (number)');
  try {
    const response2 = await axios.post(`${baseUrl}/users`, { name: 123 });
    console.log('FAIL: Should have returned 400');
  } catch (error) {
    if (error.response && error.response.status === 400) {
      console.log('PASS: Returned 400 status');
      console.log('Message:', error.response.data.message);
    } else {
      console.log('FAIL:', error.message);
    }
  }
  console.log('---');

  // Test 3: Non-string name (boolean)
  console.log('Test 3: Non-string name (boolean)');
  try {
    const response3 = await axios.post(`${baseUrl}/users`, { name: true });
    console.log('FAIL: Should have returned 400');
  } catch (error) {
    if (error.response && error.response.status === 400) {
      console.log('PASS: Returned 400 status');
      console.log('Message:', error.response.data.message);
    } else {
      console.log('FAIL:', error.message);
    }
  }
  console.log('---');

  // Test 4: Empty string name
  console.log('Test 4: Empty string name');
  try {
    const response4 = await axios.post(`${baseUrl}/users`, { name: '' });
    console.log('FAIL: Should have returned 400');
  } catch (error) {
    if (error.response && error.response.status === 400) {
      console.log('PASS: Returned 400 status');
      console.log('Message:', error.response.data.message);
    } else {
      console.log('FAIL:', error.message);
    }
  }
  console.log('---');

  // Test 5: Whitespace only name
  console.log('Test 5: Whitespace only name');
  try {
    const response5 = await axios.post(`${baseUrl}/users`, { name: '   ' });
    console.log('FAIL: Should have returned 400');
  } catch (error) {
    if (error.response && error.response.status === 400) {
      console.log('PASS: Returned 400 status');
      console.log('Message:', error.response.data.message);
    } else {
      console.log('FAIL:', error.message);
    }
  }
  console.log('---');

  // Test 6: Valid name
  console.log('Test 6: Valid name');
  try {
    const response6 = await axios.post(`${baseUrl}/users`, { name: 'Charlie' });
    console.log('PASS: Created successfully');
    console.log('Status:', response6.status);
    console.log('Response:', response6.data);
  } catch (error) {
    console.log('FAIL:', error.message);
  }
  console.log('---');

  // Test 7: Valid name with whitespace
  console.log('Test 7: Valid name with whitespace');
  try {
    const response7 = await axios.post(`${baseUrl}/users`, { name: '  David Smith  ' });
    console.log('PASS: Created successfully');
    console.log('Status:', response7.status);
    console.log('Response:', response7.data);
  } catch (error) {
    console.log('FAIL:', error.message);
  }
}

// Check if server is running
async function checkServer() {
  try {
    await axios.get('http://localhost:3000/health');
    console.log('Server is running. Starting validation tests...\n');
    return true;
  } catch (error) {
    console.log('Server is not running. Please start the server first with: node app.js');
    return false;
  }
}

async function main() {
  const isRunning = await checkServer();
  if (isRunning) {
    await testValidation();
  }
}

main().catch(console.error);

