const request = require('supertest');
const app = require('../app');

describe('POST /users', () => {
  it('should create a new user with valid name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 'Test User' })
      .expect(201);

    expect(response.body).toHaveProperty('id');
    expect(response.body.name).toBe('Test User');
    expect(response.body.email).toBe('testuser@example.com');
    expect(response.body).toHaveProperty('createdAt');
  });

  it('should return 400 when name is missing', async () => {
    const response = await request(app)
      .post('/users')
      .send({})
      .expect(400);

    expect(response.body.error).toBe('Missing required field: name');
    expect(response.body.message).toContain('required');
  });

  it('should return 400 when name is null', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: null })
      .expect(400);

    expect(response.body.error).toBe('Missing required field: name');
  });

  it('should return 400 when name is not a string (number)', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 123 })
      .expect(400);

    expect(response.body.error).toBe('Invalid field type');
    expect(response.body.message).toContain('must be a string');
  });

  it('should return 400 when name is not a string (boolean)', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: true })
      .expect(400);

    expect(response.body.error).toBe('Invalid field type');
  });

  it('should return 400 when name is not a string (object)', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: { first: 'John', last: 'Doe' } })
      .expect(400);

    expect(response.body.error).toBe('Invalid field type');
  });

  it('should return 400 when name is not a string (array)', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: ['John', 'Doe'] })
      .expect(400);

    expect(response.body.error).toBe('Invalid field type');
  });

  it('should return 400 when name is empty string', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '' })
      .expect(400);

    expect(response.body.error).toBe('Empty name field');
    expect(response.body.message).toContain('cannot be empty');
  });

  it('should return 400 when name contains only whitespace', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '   ' })
      .expect(400);

    expect(response.body.error).toBe('Empty name field');
  });

  it('should trim whitespace from valid names', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '  Trimmed Name  ' })
      .expect(201);

    expect(response.body.name).toBe('Trimmed Name');
    expect(response.body.email).toBe('trimmedname@example.com');
  });
});

describe('GET /users', () => {
  it('should return list of users', async () => {
    const response = await request(app)
      .get('/users')
      .expect(200);

    expect(Array.isArray(response.body)).toBe(true);
    expect(response.body.length).toBeGreaterThan(0);
  });
});

describe('GET /health', () => {
  it('should return health status', async () => {
    const response = await request(app)
      .get('/health')
      .expect(200);

    expect(response.body.status).toBe('ok');
    expect(response.body).toHaveProperty('timestamp');
  });
});

