const express = require('express');
const app = express();

// Middleware to parse JSON request bodies
app.use(express.json());

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// POST handler with input validation
app.post('/users', (req, res) => {
  const { name } = req.body;

  // Validate that name field exists and is a string
  if (name === undefined || name === null) {
    return res.status(400).json({
      error: 'Missing required field: name',
      message: 'The "name" field is required in the request body'
    });
  }

  if (typeof name !== 'string') {
    return res.status(400).json({
      error: 'Invalid field type',
      message: 'The "name" field must be a string'
    });
  }

  // Additional validation: check if name is not empty (optional but recommended)
  if (name.trim() === '') {
    return res.status(400).json({
      error: 'Invalid field value',
      message: 'The "name" field cannot be empty'
    });
  }

  // Process the valid request
  // For demonstration, return the created user with an ID
  const newUser = {
    id: Math.floor(Math.random() * 1000) + 3, // Generate a simple ID
    name: name.trim(),
    createdAt: new Date().toISOString()
  };

  res.status(201).json(newUser);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

